        "badge.picker.title": ["Бейджи", "Бейджи", "Badges"],
        "wh.squareAvatars": ["Все аватарки в приложении — в списке чатов, в чате, в профиле, в настройках и в поиске — становятся квадратными со скруглёнными углами. Кольцо историй вокруг таких аватарок скрывается.", "Квадратні аватари", "Makes every avatar square with rounded corners across the app. The story ring around avatars is hidden in this mode."],
        "wh.compactChatList": ["Уменьшает аватарки и отступы в списке чатов: на экран помещается больше диалогов. Несовместимо с новым видом списка чатов.", "Компактний список чатів", "Shrinks avatars and paddings in the chat list so more chats fit on screen. Not compatible with the new chat list style."],
        "wh.newChatListUI": ["Список чатов рисуется карточками с закруглёнными краями вместо сплошных строк.", "Новий список чатів (картки)", "Draws the chat list as rounded cards instead of plain rows."],
        "wh.stickerSize": ["Задаёт размер, с которым стикеры отображаются в переписке. На отправку не влияет — меняется только показ у вас.", "Розмір стікерів", "Sets how large stickers appear in chats. Affects only your view, not what you send."],
        "wh.telegramIcons": ["Возвращает стандартные иконки Telegram вместо иконок Whitegram в интерфейсе.", "Оригінальні іконки Telegram", "Restores the stock Telegram icons instead of the Whitegram ones."],
        "wh.disableChatSwipe": ["Отключает действия по свайпу на чате (архив, отключение уведомлений, удаление), чтобы случайный жест ничего не менял.", "Вимкнути свайп-опції в чатах", "Disables chat swipe actions (archive, mute, delete) so a stray gesture cannot change anything."],
        "wh.unlimitedPinned": ["Снимает лимит Telegram на число закреплённых чатов. Закрепления хранятся локально, на других устройствах лимит остаётся прежним.", "Необмежене закріплення чатів", "Removes Telegram's pinned chat limit. The extra pins are local to this device."],
        "wh.roundProfileButtons": ["Аккаунты и кнопки редактирования в настройках показываются одной горизонтальной лентой круглых кнопок с аватарками, которые можно перетаскивать, меняя порядок аккаунтов.", "Переключатель акаунтів", "Shows accounts and edit buttons as one scrollable row of round avatar buttons which can be dragged to reorder accounts."],
        "wh.roundProfileActionButtons": ["Кнопки действий в профиле (позвонить, видео, уведомления, поиск, ещё) рисуются отдельными круглыми кнопками вместо общей плашки.", "Кнопки дій у профілі (подзвонити, відео, сповіщення, пошук, ще) малюються окремими круглими кнопками замість спільної плашки.", "Draws the profile action buttons as separate round buttons instead of one bar."],
        "wh.fisheyeEffect": ["Кнопки в горизонтальной ленте увеличиваются в центре и уменьшаются к краям — эффект «рыбьего глаза» при прокрутке.", "Ефект риб'ячого ока для кнопок", "Buttons in horizontal rows scale up in the centre and shrink at the edges while scrolling."],
        "s.copyBotCallback": ["Callback кнопок ботов", "Callback кнопок ботів", "Bot Button Callback"],
        "wh.copyBotCallback": ["В контекстное меню inline-кнопок ботов добавляется пункт для копирования их callback-данных. Нужно для отладки ботов.", "Копіювати callback-дані кнопок", "Adds a menu item to copy the callback data of bot inline buttons — useful for bot debugging."],
        "wh.profileColor": ["Фон профиля заливается персональным цветом человека: цветом его NFT-подарка в статусе, цветом профиля Premium или цветом Whitegram, если он его задал.", "Персональний колір у профілі", "Fills the profile background with the person's personal colour: their NFT gift status, Premium profile colour, or a Whitegram colour."],
        "wh.avatarBlurZoom": ["При раскрытии аватарки фон вокруг неё размывается, оставляя фокус на фотографии.", "Блюр аватара при збільшенні", "Blurs the background around the avatar while it is expanded."],
        "wh.avatarBlurProfile": ["На задний фон профиля ставится размытая копия аватарки человека. Работает вместе с обоями профиля, если те не заданы.", "Блюр аватара у профілі", "Uses a blurred copy of the person's avatar as the profile background."],
        "wh.avatarBlurReduced": ["Уменьшает силу размытия аватарки на фоне профиля почти до нуля — фотография видна отчётливо.", "Зменшити блюр до мінімуму", "Reduces the avatar blur on the profile background almost to zero, so the photo stays sharp."],
        "wh.avatarBlurTint": ["Добавляет затемняющий слой поверх размытой аватарки, чтобы текст и кнопки профиля читались на светлых фото.", "Тонування блюру", "Adds a darkening layer over the blurred avatar so profile text stays readable on light photos."],
        "wh.albumArtBlur": ["На фон плеера ставится размытая обложка играющего трека.", "Блюр обкладинки треку в плеєрі", "Uses a blurred copy of the current track's cover art as the player background."],
        "wh.appBadgeColor": ["Выбор бейджа Whitegram, который показывается на Динамическом острове поверх часов.", "Колір бейджа острова", "Chooses the Whitegram badge shown on the Dynamic Island."],
        "wh.messageBorder": ["Каждому сообщению добавляется тонкая обводка выбранного цвета. Сочетается с прозрачными и полупрозрачными сообщениями.", "Обведення повідомлень", "Adds a thin outline of the chosen colour to every message bubble."],
        "wh.transparentMsgs": ["Пузыри сообщений становятся полностью прозрачными — виден только текст поверх обоев чата.", "Прозорі повідомлення", "Makes message bubbles fully transparent, leaving only the text over the wallpaper."],
        "wh.semiTransparent": ["Пузыри сообщений становятся полупрозрачными: обои просвечивают, но текст остаётся на подложке.", "Напівпрозорі повідомлення (α=0.7)", "Makes message bubbles semi-transparent so the wallpaper shows through."],
        "wh.liquidGlass": ["Под пузырями сообщений включается размытие фона вместо сплошной заливки.", "Блюр повідомлень", "Blurs the wallpaper behind message bubbles instead of filling them with colour."],
        "wh.glassMessageBubbles": ["Пузыри сообщений получают материал Liquid Glass системы: стекло с бликами и преломлением.", "Liquid Glass повідомлення", "Gives message bubbles the system Liquid Glass material with highlights and refraction."],
        "wh.liquidGlassInlineButtons": ["Inline-кнопки под сообщениями рисуются стеклом Liquid Glass вместо плоской заливки.", "Liquid Glass inline-кнопки", "Draws inline buttons under messages with the Liquid Glass material."],
        "wh.particleEffect": ["Выбор анимированных частиц (снег, звёзды и т. п.), которые падают поверх интерфейса.", "Ефект частинок", "Picks animated particles (snow, stars and so on) that fall over the interface."],
        "wh.showDeleted": ["Удалённые собеседником сообщения остаются в чате и помечаются как удалённые. Работает только для сообщений, которые приложение успело получить.", "Показувати видалені повідомлення", "Keeps messages deleted by others visible and marks them as deleted. Works only for messages the app already received."],
        "wh.deletedOpacity": ["Насколько бледно показывать удалённые сообщения, чтобы отличать их от обычных.", "Прозорість видалених", "How faded deleted messages appear compared to normal ones."],
        "wh.showEdited": ["У отредактированных сообщений можно посмотреть исходный текст до правки.", "Оригінал відредагованих", "Lets you see the original text of edited messages."],
        "wh.shortenMenu": ["В контекстное меню сообщения добавляется пункт, который сокращает длинный текст через ИИ.", "Кнопка «Скоротити» в меню", "Adds a menu item that shortens long messages with AI."],
        "wh.charCountTyping": ["Пока вы набираете сообщение, рядом с полем ввода показывается число символов.", "Лічильник символів при введенні", "Shows a live character count next to the input field while typing."],
        "wh.charCountMsgs": ["У каждого сообщения в чате показывается количество символов в нём.", "Лічильник символів у повідомленнях", "Shows the character count of every message in the chat."],
        "wh.hideMyDeleted": ["Ваши собственные удалённые сообщения не показываются как удалённые — только чужие.", "Ваші власні видалені повідомлення не показуються як видалені — лише чужі.", "Your own deleted messages are not shown as deleted — only other people's are."],
        "wh.hideMyEdited": ["Исходный текст не показывается для ваших собственных отредактированных сообщений.", "Початковий текст не показується для ваших власних відредагованих повідомлень.", "The original text is not shown for your own edited messages."],
        "wh.hideBotEdited": ["Исходный текст отредактированных сообщений ботов не показывается. Боты правят сообщения часто, поэтому это выделено отдельно.", "Початковий текст відредагованих повідомлень ботів не показується.", "The original text of edited bot messages is not shown — bots edit often, so this is a separate switch."],
        "wh.hideBotDeleted": ["Удалённые сообщения ботов не показываются вместе с остальными удалёнными.", "Видалені повідомлення ботів не показуються разом з рештою видалених.", "Deleted bot messages are not shown along with the other deleted ones."],
        "wh.doubleTapEdit": ["Двойное нажатие по своему сообщению сразу открывает его редактирование.", "Подвійний тап для редагування", "Double-tapping your own message opens it for editing right away."],
        "wh.clearDeletedCache": ["Полностью удаляет локальную базу сохранённых удалённых сообщений. Отменить нельзя.", "Очистити кеш видалених повідомлень", "Permanently clears the local database of saved deleted messages."],
        "wh.clearEditedCache": ["Полностью удаляет локальную базу исходных версий отредактированных сообщений.", "Очистити кеш змінених повідомлень", "Permanently clears the local database of original versions of edited messages."],
        "wh.clearSavedHistory": ["Удаляет сохранённые копии истории чатов, которые Whitegram хранит для восстановления.", "Очистити збережену історію чатів", "Deletes the saved chat history copies Whitegram keeps for restoring."],
        "wh.restoreChats": ["Возвращает в чаты сообщения из локальной резервной копии Whitegram.", "Відновити збережені чати", "Restores messages into chats from the local Whitegram backup."],
        "wh.saveDeletedToBackup": ["Каждое удалённое сообщение дополнительно записывается в локальную базу, которую можно экспортировать файлом.", "Зберігати видалені до бази даних", "Also writes every deleted message into a local database you can export as a file."],
        "wh.exportDeletedBackup": ["Сохраняет базу удалённых сообщений файлом, чтобы перенести её на другое устройство.", "Експорт бази видалених повідомлень", "Saves the deleted-message database to a file you can move to another device."],
        "wh.importDeletedBackup": ["Загружает базу удалённых сообщений из ранее сохранённого файла.", "Імпорт бази видалених повідомлень", "Loads a previously exported deleted-message database."],
        "wh.cameraFront": ["Кружки и истории по умолчанию записываются на фронтальную камеру.", "Фронтальна", "Records video messages and stories with the front camera by default."],
        "wh.cameraBack": ["Кружки и истории по умолчанию записываются на основную камеру.", "Задня", "Records video messages and stories with the rear camera by default."],
        "wh.cameraSettings": ["Настройки камеры Whitegram: какая камера включается по умолчанию, зум и качество записи.", "Керування камерою", "Whitegram camera settings: default camera, zoom and recording quality."],
        "camera.settings.title": ["Управление камерой", "Керування камерою", "Camera Control"],
        "camera.settings.back": ["Задняя камера", "Задня камера", "Back Camera"],
        "camera.settings.front": ["Фронтальная камера", "Фронтальна камера", "Front Camera"],
        "camera.settings.quality": ["Разрешение", "Роздільна здатність", "Quality"],
        "camera.settings.fps": ["Частота кадров", "Частота кадрів", "Frame Rate"],
        "camera.settings.wideAngle": ["0.5× для видео-кружков", "0.5× для відео-кружків", "0.5× for Video Circles"],
        "camera.settings.wideAngleSub": ["Снимать кружки на широкоугольную камеру (0.5×). Только задняя камера.", "Знімати кружечки на ширококутну камеру (0.5×). Тільки задня камера.", "Record circles with ultra-wide lens (0.5×). Back camera only."],
        "camera.settings.stock": ["Настройки камеры Telegram", "Налаштування камери Telegram", "Telegram camera settings"],
        "camera.settings.stockSub": ["Стандартные разрешение и частота кадров. Кружок сохраняет естественный угол обзора. Выключите, чтобы настроить камеру вручную.", "Стандартні роздільна здатність і частота кадрів. Кружечок зберігає природний кут огляду. Вимкніть, щоб налаштувати камеру вручну.", "Stock resolution and frame rate. Round videos keep their natural field of view. Turn off to set the camera manually."],
        "camera.settings.roundVideo": ["Видео-кружки", "Відео-кружки", "Video Circles"],
        "camera.settings.bitrate": ["Битрейт записи", "Бітрейт запису", "Recording Bitrate"],
        "camera.settings.bitrateLow": ["Низкий", "Низький", "Low"],
        "camera.settings.bitrateMed": ["Средний", "Середній", "Medium"],
        "camera.settings.bitrateHigh": ["Высокий", "Високий", "High"],
        "wh.forceDeviceMic": ["Запись всегда идёт со встроенного микрофона устройства, даже когда подключены наушники или гарнитура.", "Використовувати мікрофон пристрою", "Always records from the device microphone even when headphones are connected."],
        "wh.sendLargePhotos": ["Фотографии отправляются без пережатия Telegram, в максимальном качестве и размере.", "Надсилати великі фото (2560px)", "Sends photos without Telegram's downscaling, at full quality and size."],
        "wh.photoQuality": ["Степень сжатия JPEG при отправке фото: выше значение — лучше качество и больше размер файла.", "Якість JPEG фото", "JPEG compression level for outgoing photos: higher means better quality and a bigger file."],
        "wh.rememberCamera": ["При записи кружка включается та камера, которой вы пользовались в прошлый раз.", "Запам'ятовувати останню камеру", "Starts video message recording with the camera you used last time."],
        "wh.staticZoom": ["Зум в кружках фиксируется и не меняется при переключении камеры во время записи.", "Статичний зум при записі", "Locks the zoom level in video messages so it does not change when switching cameras."],
        "wh.alwaysHD": ["Все медиафайлы — фото, видео, кружки — отправляются в максимальном качестве.", "Завжди надсилати в HD", "Sends every media file — photos, videos, video messages — at maximum quality."],
        "wh.alwaysOnline": ["Ваш статус для всех остаётся «в сети», даже когда приложение закрыто. Требует, чтобы приложение периодически просыпалось.", "Завжди онлайн", "Keeps your status as online for everyone even when the app is closed."],
        "wh.disableOnline": ["Никто не видит вас в сети: статус всегда показывается как «был(а) недавно».", "Приховати онлайн-статус", "Nobody sees you online — your status always stays offline."],
        "wh.disableTyping": ["Собеседник не увидит статус «печатает», пока вы набираете сообщение.", "Приховати статус набору тексту", "Stops the typing indicator from being sent while you write."],
        "wh.disableRecording": ["Собеседник не увидит статус «записывает голосовое» во время записи.", "Приховати статус запису голосового", "Stops the recording indicator from being sent while you record audio."],
        "wh.disableUploading": ["Собеседник не увидит статус отправки файла, пока идёт загрузка.", "Приховати статус завантаження файлів", "Stops the upload indicator from being sent while a file is sending."],
        "wh.disableReadReceipts": ["Отправитель не увидит, что вы прочитали его сообщение. Двойные галочки у него не появятся.", "Приховати прочитання повідомлень", "Senders will not see that you read their message — no read receipts are sent."],
        "wh.disableStoryRead": ["Автор истории не увидит вас в списке просмотревших.", "Приховати перегляд сторіс", "Story authors will not see you in their viewer list."],
        "wh.readOnAction": ["Сообщения помечаются прочитанными только при вашем действии (ответ, реакция), а не при простом открытии чата.", "Читати при діях", "Marks messages as read only when you act on them, not when you merely open the chat."],
        "wh.deferredMessages": ["Отправка сообщения задерживается на 12 секунд — за это время его можно отменить.", "Відкладена відправка (12 сек)", "Delays sending by 12 seconds so you can still cancel the message."],
        "wh.fakeDeviceName": ["Подменяет название устройства, которое видно в списке активных сессий Telegram.", "Пристрій", "Replaces the device name shown in Telegram's active sessions list."],
        "wh.exportImport": ["Экспорт и импорт всех настроек Whitegram одним файлом — удобно при переустановке.", "Експорт / Імпорт", "Exports and imports all Whitegram settings as a single file."],
        "wh.fakeLocation": ["Подменяет координаты, которые отправляются при отправке геопозиции и в геочатах.", "Підміна геолокації", "Replaces the coordinates sent when you share your location."],
        "wh.onlineHistory": ["Whitegram запоминает, когда ваши контакты появлялись в сети, и строит по этому историю.", "Історія онлайну (відстежувати статуси)", "Whitegram records when your contacts come online and builds a history from it."],
        "wh.viewOnlineHistory": ["Открывает собранную историю онлайна ваших контактов.", "Переглянути історію онлайну", "Opens the collected online history of your contacts."],
        "wh.clearOnlineHistory": ["Удаляет всю собранную историю онлайна. Отменить нельзя.", "Очистити історію онлайну", "Deletes the entire collected online history."],
        "wh.disableAds": ["Убирает спонсорские сообщения из каналов и из поиска.", "Вимкнути рекламу в каналах", "Removes sponsored messages from channels and search."],
        "wh.protectedContent": ["Позволяет копировать текст, пересылать и сохранять медиа из чатов с включённой защитой контента.", "Обхід захищеного контенту", "Lets you copy, forward and save media from chats with content protection enabled."],
        "wh.removeSpoilers": ["Скрытый спойлером текст и медиа показываются сразу, без нажатия.", "Прибрати спойлери скрізь", "Reveals spoiler text and media immediately, without tapping."],
        "wh.scammerProtection": ["Профили из базы мошенников Whitegram помечаются предупреждением при открытии.", "Захист від шахраїв", "Marks profiles listed in the Whitegram scammer database with a warning."],
        "wh.warnBeforeCall": ["Перед исходящим звонком показывается подтверждение — защита от случайных нажатий.", "Попереджати перед дзвінком", "Shows a confirmation before placing a call, protecting you from accidental taps."],
        "wh.showPeerIDDC": ["В профиле показываются числовой ID пользователя и его дата-центр Telegram.", "Показувати ID та DC у профілі", "Shows the numeric user ID and Telegram data centre in profiles."],
        "wh.timestampSecs": ["У сообщений и статусов время показывается с секундами.", "Показувати секунди в мітці часу", "Shows seconds in message and status timestamps."],
        "wh.fullViewCount": ["У постов в каналах показывается точное число просмотров вместо округлённого.", "Повні перегляди", "Shows the exact view count on channel posts instead of a rounded number."],
        "wh.hidePhone": ["Ваш номер телефона убирается из вашего же профиля на экране — чтобы не светить его при показе экрана.", "Сховати номер телефону", "Hides your phone number in your own profile screen so it is not exposed when sharing your screen."],
        "wh.chatCreationDate": ["В профиле чата или канала показывается дата его создания.", "Дата створення чату/каналу", "Shows the creation date in a chat or channel profile."],
        "wh.visualUsername": ["Подменяет отображаемый юзернейм в вашем профиле только визуально — для других он остаётся прежним.", "Візуальний юзернейм", "Visually replaces the username shown in your profile; other people still see the real one."],
        "wh.formattingToolbar": ["Над клавиатурой появляется панель форматирования: жирный, курсив, ссылка, код, цитата и другое.", "Панель форматування над клавіатурою", "Adds a formatting toolbar above the keyboard: bold, italic, link, code, quote and more."],
        "wh.localPremium": ["Локально включает премиум-функции интерфейса. Серверные ограничения Telegram при этом не снимаются.", "Локальний преміум (прибирає обмеження)", "Enables Premium interface features locally. Telegram's server-side limits still apply."],
        "wh.translateAlways": ["Кнопка перевода в контекстном меню показывается всегда, даже если язык совпадает с вашим.", "Кнопка «Перекласти» завжди видима", "Always shows the translate button, even when the language matches yours."],
        "wh.localTranslation": ["Перевод сообщений идёт через Google вместо переводчика Telegram Premium.", "Переклад повідомлень через Google", "Translates messages through Google instead of Telegram Premium's translator."],
        "wh.translateBeforeSending": ["В меню отправки появляется вариант «С переводом»: сообщение переводится перед отправкой.", "Перекладати текст з меню надсилання", "Adds a send option that translates your message before sending it."],
        "wh.voiceTranslation": ["Голосовые распознаются встроенным движком Apple, без подписки Telegram Premium.", "Транскрипція голосових через Apple Speech", "Transcribes voice messages with Apple's on-device engine, no Telegram Premium needed."],
        "wh.antiCensorship": ["Дополнительно шифрует трафик приложения, чтобы обойти блокировки и анализ трафика провайдером.", "Покращене шифрування трафіку", "Adds extra traffic encryption to bypass ISP blocking and inspection."],
        "wh.hideGalleryCamera": ["Убирает плитку камеры из панели выбора медиа при отправке.", "Сховати камеру в галереї", "Removes the camera tile from the media picker."],
        "wh.cleanMetadata": ["Из фото и видео перед отправкой вырезаются EXIF и GPS — получатель не узнает модель камеры и место съёмки.", "EXIF / GPS", "Strips EXIF and GPS from photos and videos before sending, hiding camera model and location."],
        "wh.saveChatHistory": ["Whitegram хранит копию сообщений чата, чтобы их можно было восстановить после удаления.", "Зберігати історію чатів", "Whitegram keeps a copy of chat messages so they can be restored after deletion."],
        "wh.zalgoFilter": ["Убирает «падающий» текст с комбинированными символами, который ломает вёрстку сообщений.", "Zalgo-фільтр (прибрати спотворення тексту)", "Removes zalgo text with stacked combining characters that breaks message layout."],
        "wh.inAppVibration": ["Добавляет тактильный отклик на действия, где Telegram его не даёт: нажатия, свайпы, отправку.", "Вібрація в застосунку", "Adds haptic feedback to actions where Telegram gives none: taps, swipes, sending."],
        "wh.hideReactions": ["Реакции под сообщениями не показываются вовсе.", "Сховати реакції", "Hides reactions under messages entirely."],
        "wh.showActionTime": ["У системных сообщений (вход в группу, звонок и т. п.) показывается полное время.", "Показувати час у дій", "Shows the full timestamp on service messages such as joins and calls."],
        "wh.saveViewOnce": ["Одноразовые фото, видео и кружки сохраняются в галерею при просмотре.", "Зберігати одноразові медіа в галерею", "Saves view-once photos, videos and video messages to your gallery when you open them."],
        "wh.unlimitedStickers": ["Снимает лимит на число недавних стикеров.", "Безкінечні стікери", "Removes the limit on how many recent stickers are kept."],
        "wh.sendAccel": ["Отправка файлов идёт в несколько потоков — быстрее на хорошем канале, выше нагрузка на сеть.", "Прискорення відправки", "Uploads files over several connections — faster on a good link, heavier on the network."],
        "wh.downloadAccel": ["Загрузка файлов идёт в несколько потоков — быстрее на хорошем канале, выше нагрузка на сеть.", "Прискорення завантаження", "Downloads files over several connections — faster on a good link, heavier on the network."],
        "wh.autoFormat": ["Текст автоматически форматируется при отправке: ссылки, код и разметка распознаются без ручного выделения.", "Авто-форматування тексту", "Formats your text automatically on send: links, code and markup are detected for you."],
        "wh.autoFormatMixedScript": ["При отправке часть кириллицы заменяется похожими по звучанию латинскими буквами: «Заказать» → «Zаkаzаtь». Разметка, ссылки и эмодзи не съезжают.", "Під час надсилання частина кирилиці замінюється схожими за звучанням латинськими літерами.", "On send, some Cyrillic letters are swapped for Latin look‑alikes of the same sound. Formatting, links and emoji stay in place."],
        "wh.stopAfterVoice": ["После голосового сообщения автовоспроизведение следующего не начинается.", "Не слухати наст. голосове", "Stops autoplay after a voice message instead of continuing to the next one."],
        "wh.saveFavorites": ["В меню сообщения появляется пункт для быстрого сохранения его в избранное.", "Кнопка «В обране» в меню повідомлень", "Adds a menu item to quickly save a message to your favourites."],
        "wh.noChannelSwitch": ["Отключает автоматический переход к следующему каналу при прокрутке до конца.", "Не перемикатися між каналами", "Disables automatically jumping to the next channel when you scroll to the end."],
        "wh.showOnlineDotInChats": ["Зелёная точка онлайна у аватарки отправителя в группах, темах и каналах. В личных чатах и чатах с ботами не показывается.", "Зелена крапка онлайну біля аватарки відправника в групах, темах і каналах. У особистих чатах і чатах з ботами не показується.", "A green online dot on the sender's avatar in groups, topics and channels. Not shown in private chats or bot chats."],
        "wh.foldersAtBottom": ["Список папок переезжает из шапки вниз, к нижней панели вкладок.", "Теки знизу", "Moves the folder list from the header down to the tab bar."],
        "wh.hideGifts": ["Вкладка «Подарки» в профилях не показывается.", "Сховати подарунки", "Hides the Gifts tab in profiles."],
        "wh.highlightMentions": ["Сообщения собеседника становятся полупрозрачными, когда он отвечает именно вам — ответ заметнее в общей переписке.", "Напівпрозоро, коли згадують", "Fades the other person's messages when they reply directly to you, making the reply stand out."],
        "wh.clickSound": ["Нажатия по элементам интерфейса сопровождаются звуком.", "Звук при натисненні", "Plays a click sound on interface taps."],
        "wh.hideDescriptions": ["Скрывает эти пояснения под названиями опций — меню становится компактнее.", "Сховати описи функцій", "Hides these explanations under option titles, making the menu more compact."],
        "wh.accountSwitcher": ["В шапке списка чатов появляется кнопка быстрого переключения между вашими аккаунтами.", "Перемикач акаунту в шапці", "Adds a quick account-switch button to the chat list header."],
        "wh.hideChatListTitle": ["Убирает крупный заголовок «Чаты» — список начинается сразу с диалогов.", "Сховати напис «Чати»", "Removes the large “Chats” title so the list starts right away."],
        "wh.hidePremiumBadge": ["Скрывает премиум-значок рядом с вашим именем в шапке списка чатов.", "Сховати преміум-статус у шапці", "Hides the Premium badge next to your name in the chat list header."],
        "wh.hideContactsTab": ["Убирает вкладку «Контакты» из нижней панели.", "Сховати вкладку «Контакти»", "Removes the Contacts tab from the bottom bar."],
        "wh.hideCallsTab": ["Убирает вкладку «Звонки» из нижней панели.", "Сховати вкладку «Дзвінки»", "Removes the Calls tab from the bottom bar."],
        "wh.hideStories": ["Лента историй сверху списка чатов не показывается.", "Сховати сторіс", "Hides the stories strip above the chat list."],
        "wh.hideSearchBar": ["Убирает кнопку поиска (лупу) из нижней панели вкладок.", "Сховати кнопку пошуку (лупа)", "Removes the search button from the bottom tab bar."],
        "wh.showPostsFeed": ["Добавляет вкладку с лентой постов из ваших каналов.", "Стрічка постів з каналів", "Adds a tab with a feed of posts from your channels."],
        "wh.separateProfileTab": ["Как в Telegram для Android: рядом с «Настройками» появляется отдельная вкладка «Профиль».", "Як у Telegram для Android: поряд із «Налаштуваннями» з’являється окрема вкладка «Профіль».", "Like Telegram for Android: a separate Profile tab appears next to Settings."],
        "wh.hideTabLabels": ["Подписи вкладок в нижней панели скрываются, а иконки центрируются по высоте панели.", "Сховати підписи вкладок", "Hides tab titles in the bottom bar and centres the icons vertically."],
        "wh.tabBarScale": ["Высота нижней панели вкладок в процентах от стандартной.", "Висота панелі", "Height of the bottom tab bar as a percentage of the default."],
        "wh.tabBarWidth": ["Ширина нижней панели вкладок в процентах от стандартной.", "Ширина панелі", "Width of the bottom tab bar as a percentage of the default."],
        "wh.autoConnect": ["Прокси включается автоматически при запуске приложения.", "Автопідключення проксі", "Turns the proxy on automatically when the app starts."],
        "wh.localStars": ["Локально подменяет отображаемый баланс звёзд. На реальный баланс и покупки не влияет.", "Локальний баланс зірок", "Locally replaces the displayed Stars balance. Your real balance and purchases are unaffected."],
        "wh.starsCount": ["Значение баланса звёзд, которое будет показано.", "Кількість зірок", "The Stars balance value that will be displayed."],
        "wh.starsCustom": ["Ввести произвольное значение баланса звёзд.", "Своє значення", "Enter a custom Stars balance value."],
        "wh.customFont": ["Заменяет системный шрифт интерфейса на выбранный вами.", "Увімкнути власний шрифт", "Replaces the interface font with one of your choice."],
        "s.persistentNotifications": ["Постоянные уведомления", "Постійні сповіщення", "Persistent Notifications"],
        "wh.persistentNotifications": ["Уведомления Whitegram остаются в шторке, пока вы их не уберёте вручную.", "Постійні сповіщення", "Whitegram notifications stay in the notification centre until you dismiss them."],
        "info.persistentNotifications": ["Может сильно увеличить расход батареи, так как Whitegram будет вечно висеть в фоне, пока вы его сами не уберёте.", "Може сильно збільшити витрату батареї, тому що Whitegram буде постійно працювати у фоні, доки ви самі його не закриєте.", "May significantly increase battery usage because Whitegram will stay in the background until you close it manually."],
        "wh.keychainAccounts": ["Резервные копии сессий аккаунтов в Keychain: их можно сохранить и восстановить после переустановки приложения, не входя заново по коду.", "Акаунти в Keychain", "Account session backups in the Keychain — save them and restore your accounts after reinstalling without logging in again."],
        "wh.botAccounts": ["Подключите своего бота обычным аккаунтом и читайте его переписку прямо здесь. Токен подставляется сам — выбирать его в BotFather не нужно.", "Підключіть свого бота звичайним акаунтом.", "Connect your own bot as a regular account and read its chats right here. The token is filled in for you — no BotFather needed."],
        "wh.trackLastOnline": ["Whitegram запоминает время последнего появления контакта в сети.", "Зберігати останній онлайн", "Whitegram records when each contact was last online."],
        "wh.saveReadDates": ["Whitegram сохраняет даты прочтения ваших сообщений собеседниками.", "Зберігати дату прочитання", "Whitegram saves the dates your messages were read."],
        "wh.exportDiag": ["Копирует техническую информацию о сборке и настройках — для отправки в поддержку.", "Скопіювати діагностику", "Copies technical build and settings information to send to support."],
        "wh.managePlugins": ["Установка и удаление плагинов Whitegram.", "Управління плагінами", "Install and remove Whitegram plugins."],
        "wh.wgChannel": ["Канал с новостями Whitegram: что нового в сборках и когда выйдет следующая.", "Канал з новинами Whitegram: що нового у збірках і коли вийде наступна.", "The Whitegram news channel: what is new in each build and when the next one lands."],
        "wh.wgDeveloper": ["Личный чат с автором Whitegram — сюда пишут про ошибки и просят новые функции.", "Особистий чат з автором Whitegram — сюди пишуть про помилки й просять нові функції.", "A direct chat with the author of Whitegram — report bugs and request features here."],
        "wh.openlockVPN": ["Открывает бот Openlock — это отдельный сторонний VPN, в Whitegram его нет.", "Відкриває бот Openlock — це окремий сторонній VPN, у Whitegram його немає.", "Opens the Openlock bot — a separate third-party VPN, not part of Whitegram."],
        "wh.language": ["Язык интерфейса Whitegram.", "Мова інтерфейсу", "The Whitegram interface language."],
        "di.appearance": ["«Квадратные аватары» меняют форму фотографий. «Компактный список» уменьшает аватары и отступы. «Размер стикеров» масштабирует стикеры в чате (10–200%). «Оригинальные иконки Telegram» добавляет их в меню выбора иконки. «Круглые кнопки» убирает текст под кнопками и делает их круглыми. «Персональный цвет» использует профильный цвет как фон. «Блюр аватара» при увеличении аватарки показывает размытый фон.", "«Квадратні аватари» змінюють форму фотографій. «Компактний список» зменшує аватари та відступи. «Розмір стікерів» масштабує стікери в чаті (10–200%). «Оригінальні іконки Telegram» додає їх до меню вибору іконки. «Круглі кнопки» прибирає текст під кнопками і робить їх круглими. «Персональний колір» використовує колір профілю як фон. «Блюр аватара» при збільшенні аватарки показує розмитий фон.", "«Square Avatars» changes photo shapes. «Compact List» reduces avatars and padding. «Sticker Size» scales stickers in chat (10–200%). «Original Telegram Icons» adds them to the icon picker. «Round Buttons» removes text under profile buttons. «Profile Color» uses the profile color as background. «Avatar Blur» shows a blurred background when zooming in on an avatar."],
        "di.bubbles": ["«Обводка» добавляет тонкую рамку вокруг каждого сообщения. «Прозрачные» скрывают фон — виден только текст. «Полупрозрачные» делают фон видимым на 70%. «Liquid Glass» заменяет фон пузырьков блюром. Опции взаимно исключают друг друга.", "«Обведення» додає тонку рамку навколо кожного повідомлення. «Прозорі» приховують фон — видно лише текст. «Напівпрозорі» роблять фон видимим на 70%. «Liquid Glass» замінює фон бульбашок блюром. Опції взаємно виключають одна одну.", "«Border» adds a thin frame around each message. «Transparent» hides the background — only text is visible. «Semi-transparent» makes the background 70% visible. «Liquid Glass» replaces bubble backgrounds with blur. Options are mutually exclusive."],
        "di.showDeleted": ["Удалённые сообщения остаются в чате полупрозрачными со значком 🗑. Повторное удаление убирает их окончательно.", "Видалені повідомлення залишаються в чаті напівпрозорими зі значком 🗑. Повторне видалення прибирає їх остаточно.", "Deleted messages stay semi-transparent in chat with a 🗑 icon. Deleting again removes them permanently."],
        "di.showEdited": ["Оригинальный текст отображается зачёркнутым под сообщением. Значок ✏️ рядом со временем указывает на редактирование.", "Оригінальний текст відображається закресленим під повідомленням. Значок ✏️ поруч із часом вказує на редагування.", "The original text is shown crossed-out below the message. The ✏️ icon next to the timestamp indicates an edit."],
        "di.cache": ["«Кэш удалённых» убирает метки просмотра. «Кэш изменённых» стирает историю редактирования. «Сохранённая история» сбрасывает метки удаления (сообщения, сохранённые через «Сохранять историю»).", "«Кеш видалених» прибирає позначки перегляду. «Кеш змінених» стирає історію редагування. «Збережена історія» скидає позначки видалення (повідомлення, збережені через «Зберігати історію»).", "«Deleted Cache» removes view markers. «Edited Cache» erases edit history. «Saved History» resets deletion markers (messages saved via «Save Chat History»)."],
        "di.camera": ["Выберите камеру по умолчанию для кружков.", "Виберіть камеру за замовчуванням для кружечків.", "Choose the default camera for video circles."],
        "di.ghost": ["Каждая опция независима. «Читать при действиях» — помечает сообщения прочитанными при любом действии с собеседником.", "Кожна опція незалежна. «Читати при діях» — позначає повідомлення прочитаними при будь-якій дії із співрозмовником.", "Each option is independent. «Read on Action» marks messages as read when any interaction with a contact occurs."],
        "di.privacy": ["«Отключить рекламу» скрывает спонсорские сообщения. «Обход защищённого контента» — разблокировка пересылки, скриншотов, сохранения медиа из защищённых каналов; одноразовый контент не исчезает; снятие блюра с платных медиа. «Защита от мошенников» предупреждает в профилях из базы скамеров Whitegram.", "«Вимкнути рекламу» приховує спонсорські повідомлення. «Обхід захищеного контенту» — розблокування пересилання, скриншотів, збереження медіа із захищених каналів; одноразовий контент не зникає; зняття блюру з платних медіа. «Захист від шахраїв» попереджає в профілях із бази скамерів Whitegram.", "«Disable Ads» hides sponsored messages. «Protected Content Bypass» unlocks forwarding, screenshots, and saving media from protected channels; view-once content stays; removes blur from paid media. «Scammer Protection» warns in profiles from the Whitegram scammer database."],
        "di.info": ["«ID и DC» добавляет технические данные в профиль. «Секунды» показывают точное время. «Полные просмотры» — реальное число (1 234 вместо 1К). «Скрыть номер» убирает номер из профиля. «Дата создания» — дата основания канала/группы.", "«ID та DC» додає технічні дані в профіль. «Секунди» показують точний час. «Повні перегляди» — реальне число (1 234 замість 1К). «Сховати номер» прибирає номер із профілю. «Дата створення» — дата заснування каналу/групи.", "«ID & DC» adds technical data to profiles. «Seconds» shows exact timestamps. «Full Views» shows the real number (1,234 instead of 1K). «Hide Phone» removes the number from your profile. «Creation Date» shows when a channel/group was founded."],
        "di.misc": ["«Панель форматирования» показывает кнопки форматирования над клавиатурой. «Перевести» всегда показывает кнопку перевода независимо от языка. «Максимальная скорость» увеличивает число параллельных загрузок до 16. «Сохранять историю» сохраняет удалённые сообщения в локальную базу — восстановите чат через меню «Ещё» в профиле собеседника.", "«Панель форматування» показує кнопки форматування над клавіатурою. «Перекласти» завжди показує кнопку перекладу незалежно від мови. «Максимальна швидкість» збільшує кількість паралельних завантажень до 16. «Зберігати історію» зберігає видалені повідомлення в локальну базу — відновіть чат через меню «Ще» в профілі співрозмовника.", "«Formatting Toolbar» shows formatting buttons above the keyboard. «Translate» always shows the translate button regardless of language. «Max Speed» increases parallel downloads to 16. «Save History» saves deleted messages to a local database — restore chats via the «More» menu in a contact's profile."],
        "di.interface": ["Позволяет убрать ненужные разделы из настроек Telegram. Хотя бы один основной раздел должен оставаться видимым.", "Дозволяє прибрати непотрібні розділи з налаштувань Telegram. Принаймні один основний розділ має залишатися видимим.", "Allows you to hide unwanted sections from Telegram settings. At least one core section must remain visible."],
        "di.tabs": ["Скрывает ненужные вкладки из нижней панели навигации. «Подписи» убирает текст под иконками. «Высота»/«Ширина» масштабируют панель (50–150%). Требуется перезапуск.", "Приховує непотрібні вкладки з нижньої панелі навігації. «Підписи» прибирає текст під іконками. «Висота»/«Ширина» масштабують панель (50–150%). Потрібен перезапуск.", "Hides unwanted tabs from the bottom navigation bar. «Labels» removes text under icons. «Height»/«Width» scales the bar (50–150%). Restart required."],
        "di.stars": ["Отображает произвольное число звёзд в профиле. Визуальный эффект — реальный баланс не изменяется.", "Відображає довільне число зірок у профілі. Візуальний ефект — реальний баланс не змінюється.", "Displays a custom star count in your profile. Visual effect only — real balance is unchanged."],
        "di.fonts": ["Нажмите «Выбрать файл шрифта» и откройте .ttf/.otf файл прямо из приложения Файлы. Шрифт применится после перезапуска.", "Натисніть «Вибрати файл шрифту» і відкрийте .ttf/.otf файл безпосередньо з програми Файли. Шрифт застосується після перезапуску.", "Tap «Select Font File» and open a .ttf/.otf file directly from the Files app. The font applies after a restart."],
        "di.sessions": ["Сохраняет ключи авторизации в iOS Keychain. При переустановке нажмите «Восстановить» для входа без повторной авторизации.", "Зберігає ключі авторизації в iOS Keychain. При перевстановленні натисніть «Відновити» для входу без повторної авторизації.", "Saves authorization keys in iOS Keychain. After reinstallation, tap «Restore» to log in without re-authorizing."],
        "di.spy": ["«Последний онлайн» запоминает приблизительное время активности даже при скрытом статусе. «Дата прочтения» сохраняет локально когда было прочитано сообщение.", "«Останній онлайн» запам'ятовує приблизний час активності навіть при прихованому статусі. «Дата прочитання» зберігає локально, коли було прочитано повідомлення.", "«Last Online» remembers approximate activity time even when the status is hidden. «Read Date» saves locally when a message was read."],
        "di.analytics": ["Показывает текущее состояние системы. Кнопка «Скопировать диагностику» копирует полный отчёт в буфер.", "Показує поточний стан системи. Кнопка «Скопіювати діагностику» копіює повний звіт у буфер.", "Shows the current system state. The «Copy Diagnostics» button copies the full report to the clipboard."],
        "di.plugins": ["JS-плагины расширяют функциональность Whitegram без пересборки. Плагины выполняются в изолированной среде JavaScriptCore.", "JS-плагіни розширюють функціональність Whitegram без перекомпіляції. Плагіни виконуються в ізольованому середовищі JavaScriptCore.", "JS plugins extend Whitegram without rebuilding. Plugins run in an isolated JavaScriptCore environment."],
        "di.openlockVPN": ["VPN от разработчика Whitegram. Даёт доступ к открытому интернету с блокировкой рекламы и телеметрии. Обходит замедление и «Белые списки» операторов РФ.", "VPN від розробника Whitegram. Надає доступ до відкритого інтернету з блокуванням реклами та телеметрії. Обходить сповільнення та «Білі списки» операторів РФ.", "VPN by the Whitegram developer. Provides open internet access with ad and telemetry blocking. Bypasses throttling and Russian ISP whitelists."],
        "particle.off": ["Выкл.", "Вимк.", "Off"],
        "particle.snow": ["Снег ❄️", "Сніг ❄️", "Snow ❄️"],
        "particle.autumn": ["Осень 🍂", "Осінь 🍂", "Autumn 🍂"],
        "fmt.off": ["Выкл", "Вимк", "Off"],
        "fmt.bold": ["Жирный", "Жирний", "Bold"],
        "fmt.italic": ["Курсив", "Курсив", "Italic"],
        "fmt.mono": ["Моноширинный", "Моноширинний", "Monospace"],
        "fmt.strike": ["Зачёркнутый", "Закреслений", "Strikethrough"],
        "fmt.spoiler": ["Спойлер", "Спойлер", "Spoiler"],
        "accel.off": ["Выкл (6 потоков)", "Вимк (6 потоків)", "Off (6 threads)"],
        "accel.4": ["4 потока", "4 потоки", "4 threads"],
        "accel.8": ["8 потоков", "8 потоків", "8 threads"],
        "accel.16": ["16 потоков", "16 потоків", "16 threads"],
        "m.expandMessage": ["Развернуть сообщение", "Розгорнути повідомлення", "Expand Message"],
        "m.shorten": ["Сократить", "Скоротити", "Shorten"],
