        "wh.profileLyricAnimation": ["Строчка проявляется по словам, как в караоке.", "Рядок проявляється по словах, як у караоке.", "The line reveals itself word by word, karaoke style."],
        "wh.profileQuote": ["Произвольная цитата в профиле — своя фраза вместо строчки из песни.", "Довільна цитата в профілі — своя фраза замість рядка з пісні.", "A free-form quote on your profile — your own words instead of a song line."],
        "wh.profileQuoteEditor": ["Текст цитаты, который увидят в вашем профиле.", "Текст цитати, який побачать у вашому профілі.", "The quote text people will see on your profile."],
        "s.musicCardStyle": ["Своя карточка\nиграющего трека", "Своя картка\nтреку, що грає", "Custom now-playing\ncard"],
        "wh.lightChatUI": ["Заменяет стеклянный материал панелей и кнопок обычным размытием. Из трёх замен стекла активна только одна: эта опция выключает «телеграмовский аналог» и «обычный цвет Telegram».", "Замінює скляний матеріал панелей і кнопок звичайним розмиттям. Із трьох замін скла активна лише одна: ця опція вимикає «телеграмівський аналог» і «звичайний колір Telegram».", "Replaces the glass material on panels and buttons with a plain blur. Only one glass replacement can be active: this option turns off ‘Telegram's own glass’ and ‘Telegram color’."],
        "wh.classicInterface": ["Возвращает интерфейс Telegram 11.15: таб-бар, шапки, папки, поле ввода и панели — как до перехода на Liquid Glass.", "Повертає інтерфейс Telegram 11.15: таб-бар, заголовки, теки, поле введення та панелі — як до переходу на Liquid Glass.", "Restores the Telegram 11.15 interface: tab bar, headers, folders, input field and panels, the way they were before Liquid Glass."],
        "wh.oledMode": ["Чистый чёрный фон вместо тёмно-серого — экономит батарею на OLED-экранах.", "Чистий чорний фон замість темно-сірого — заощаджує батарею на OLED-екранах.", "A pure black background instead of dark grey — saves battery on OLED screens."],
        "wh.mutualContactsCondition": ["Функция применяется только к людям, с которыми вы взаимно есть в контактах.", "Якщо ви обидва взаємно в контактах", "Applies only to people who have you in their contacts and vice versa."],
        "wh.newChatHeaderStyle": ["Шапка чата рисуется в обновлённом стиле Whitegram: другая компоновка имени, статуса и кнопок.", "Новий вигляд заголовка чату", "Draws the chat header in the updated Whitegram style with a different layout of name, status and buttons."],
        "wh.showRAMUsage": ["Под часами в статус-баре показывается текущее потребление оперативной памяти приложением.", "Показувати використання ОЗУ під годинником", "Shows the app's current memory usage under the clock in the status bar."],
        "wh.showRegistrationDateCard": ["В профиле показывается приблизительная дата регистрации аккаунта, рассчитанная по его ID.", "Показувати приблизну дату реєстрації", "Shows an approximate account registration date in profiles, estimated from the user ID."],
        "wh.unlimitedFavoriteStickers": ["Снимает лимит на число избранных стикеров.", "Безкінечні вибрані стікери", "Removes the limit on favourite stickers."],
        "wh.vcUseProxy": ["Запросы смены голоса идут через сервер Whitegram — работает там, где сервис недоступен напрямую.", "Маршрут запиту", "Routes voice-changer requests through the Whitegram server, so it works where the service is blocked."],
        "wh.videoChatBackground": ["Вместо обоев чата проигрывается выбранное видео — по всему интерфейсу переписки.", "Відео на тлі чату", "Plays a chosen video instead of the chat wallpaper across the chat interface."],
        "wh.profilePhotoWallpaper": ["На фон профиля ставятся выбранные обои. Имеет приоритет над персональным цветом профиля.", "Шпалери профілю", "Sets a chosen wallpaper as the profile background. Takes priority over the personal profile colour."],
        "wh.whitegramNotifications": ["Локальные уведомления Whitegram о событиях, которых нет в стандартных уведомлениях Telegram.", "Локальні сповіщення Whitegram", "Local Whitegram notifications about events Telegram does not notify you about."],
        "wh.wideChannelPosts": ["Посты в каналах занимают всю ширину экрана без боковых отступов.", "Широкі пости в каналах", "Makes channel posts span the full screen width without side margins."],
