        "plugins.permissions.none": ["Плагин не запрашивает особого доступа.", "Плагін не запитує особливого доступу.", "This plugin requests no special access."],
        "plugins.permissions.installFooter": ["Список собран из заголовка плагина и из его кода. Выключенное разрешение плагин не получит.", "Список зібрано із заголовка плагіна та з його коду. Вимкнений дозвіл плагін не отримає.", "The list comes from the plugin header and from its code. A permission left off will not be granted."],
        "plugins.permissions.sensitiveFooter": ["Красным отмечен доступ к переписке и аккаунту — он выключен по умолчанию.", "Червоним позначено доступ до листування й акаунта — його вимкнено за замовчуванням.", "Access to your messages and account is marked red and is off by default."],
        "plugins.permissions.detailFooter": ["Разрешение можно отобрать в любой момент. Плагин получит отказ при следующем обращении.", "Дозвіл можна забрати будь-коли. Плагін отримає відмову під час наступного звернення.", "You can revoke a permission at any time; the plugin is refused on its next call."],
        "plugins.permission.requestTitleFormat": ["«%@» запрашивает доступ", "«%@» запитує доступ", "“%@” requests access"],
        "plugins.permission.allow": ["Разрешить", "Дозволити", "Allow"],
        "plugins.permission.deny": ["Запретить", "Заборонити", "Deny"],
        "plugins.data.section": ["Данные", "Дані", "Data"],
        "plugins.data.clear": ["Очистить данные", "Очистити дані", "Clear Data"],
        "plugins.data.empty": ["Пусто", "Порожньо", "Empty"],
        "plugins.data.footer": ["Всё, что плагин сохранил: настройки, файлы и его хранилище. Данные стираются и при удалении плагина.", "Усе, що плагін зберіг: налаштування, файли та його сховище. Дані стираються й під час видалення плагіна.", "Everything the plugin saved: settings, files and its storage. Data is also erased when the plugin is deleted."],
        "plugins.data.clearTitle": ["Очистить данные плагина?", "Очистити дані плагіна?", "Clear plugin data?"],
        "plugins.data.clearMessageFormat": ["Настройки и файлы «%@» будут удалены без возможности восстановления. Сам плагин останется.", "Налаштування та файли «%@» буде видалено без можливості відновлення. Сам плагін залишиться.", "The settings and files of “%@” will be permanently deleted. The plugin itself stays."],
        "plugins.data.cleared": ["Данные плагина очищены", "Дані плагіна очищено", "Plugin data cleared"],
        "plugins.safeMode.title": ["Безопасный режим", "Безпечний режим", "Safe Mode"],
        "plugins.safeMode.message": ["Прошлый запуск не завершился, поэтому приложение открылось без плагинов. Включите их по одному, чтобы найти виновника.", "Минулий запуск не завершився, тому застосунок відкрився без плагінів. Вмикайте їх по одному, щоб знайти винуватця.", "The previous launch did not finish, so the app started without plugins. Enable them one by one to find the culprit."],
        "plugins.safeMode.messageFormat": ["Прошлый запуск завис на плагине «%@», поэтому он выключен, а приложение открылось без плагинов.", "Минулий запуск завис на плагіні «%@», тому його вимкнено, а застосунок відкрився без плагінів.", "The previous launch hung on “%@”, so it has been disabled and the app started without plugins."],
        "plugins.hang.disabledFormat": ["«%@» подвешивал приложение и был выключен", "«%@» підвішував застосунок і був вимкнений", "“%@” kept freezing the app and was disabled"],
        "sheet.details": ["Подробности", "Докладніше", "Details"],
        "sheet.info": ["Информация", "Інформація", "Information"],
        "s.vcInCalls": ["Менять голос\nи в звонках", "Змінювати голос\nі в дзвінках", "Change Voice\nin Calls Too"],
        "wh.vcInCalls": ["Выбранный голос звучит и в звонках: личных, групповых, видеочатах и конференциях. Собеседники сразу слышат изменённый голос.", "Вибраний голос звучить і в дзвінках: особистих, групових, відеочатах і конференціях. Співрозмовники одразу чують змінений голос.", "The selected voice is used in calls too: private, group, video chats and conferences. Other participants hear the changed voice right away."],
        "transfer.title": ["TData / Session", "TData / Session", "TData / Session"],
        "transfer.menuItem": ["TData / Session", "TData / Session", "TData / Session"],
        "transfer.import": ["Импорт аккаунтов", "Імпорт акаунтів", "Import accounts"],
        "transfer.export": ["Экспорт аккаунтов", "Експорт акаунтів", "Export accounts"],
        "transfer.hint": ["Импорт добавляет аккаунт из файла Telethon или Pyrogram (.session; у Telethon выберите вместе с ним .json), из папки tdata Telegram Desktop или из архива с такими файлами — входить по коду не нужно. Экспорт складывает выбранные аккаунты в архив с парами .session и .json.", "Імпорт додає акаунт з файлу Telethon або Pyrogram (.session; для Telethon виберіть разом із ним .json), з теки tdata Telegram Desktop або з архіву з такими файлами — входити за кодом не потрібно. Експорт складає обрані акаунти в архів з парами .session і .json.", "Import adds an account from a Telethon or Pyrogram file (.session; for Telethon pick its .json too), from a Telegram Desktop tdata folder, or from an archive of them — no login code needed. Export packs the selected accounts into an archive of .session and .json pairs."],
        "transfer.errMissingUserId": ["В %1 нет идентификатора аккаунта. Для файла Telethon выберите вместе с ним .json (поле id).", "У %1 немає ідентифікатора акаунта. Для файлу Telethon виберіть разом із ним .json (поле id).", "%1 has no account ID. For a Telethon file, pick its .json (with the id field) as well."],
        "transfer.nothingFound": ["Среди выбранного нет ни файлов .session, ни папки tdata.", "Серед вибраного немає ні файлів .session, ні теки tdata.", "The selection contains no .session files and no tdata folder."],
        "transfer.result.checking": ["Аккаунты добавлены — проверяем, принимает ли их Telegram:", "Акаунти додано — перевіряємо, чи приймає їх Telegram:", "Accounts added — checking that Telegram accepts them:"],
        "transfer.result.rejected": ["Эти аккаунты не появились: Telegram не принял ключ из файла. Так бывает, если сессию завершили на другом устройстве или тот же файл одновременно работает где-то ещё — тогда сервер отзывает ключ.", "Ці акаунти не з’явилися: Telegram не прийняв ключ із файлу. Так буває, якщо сесію завершили на іншому пристрої або той самий файл одночасно працює деінде — тоді сервер відкликає ключ.", "These accounts did not come up: Telegram rejected the key from the file. This happens when the session was terminated on another device or the same file is in use elsewhere at the same time — the server then revokes the key."],
        "transfer.pickAccounts": ["Какие аккаунты выгрузить?", "Які акаунти вивантажити?", "Which accounts to export?"],
        "transfer.all": ["Все аккаунты", "Усі акаунти", "All accounts"],
        "transfer.importedFormat": ["Добавлено аккаунтов: %1", "Додано акаунтів: %1", "Accounts added: %1"],
        "transfer.nothingImported": ["Ни одного аккаунта добавить не удалось", "Жодного акаунта додати не вдалося", "No accounts could be added"],
        "transfer.unpackFailed": ["Архив не распаковался", "Архів не розпакувався", "The archive could not be unpacked"],
        "transfer.importFiles": ["Добавить файлы .session", "Додати файли .session", "Add .session files"],
        "transfer.pickAccountsHint": ["Выберите, какой аккаунт выгрузить в файлы Telethon (.session и .json).", "Виберіть, який акаунт вивантажити у файли Telethon (.session та .json).", "Pick which account to export as Telethon files (.session and .json)."],
        "transfer.accountsSection": ["Аккаунты", "Акаунти", "Accounts"],
        "transfer.replaceTitle": ["Запись уже есть", "Запис уже є", "A record already exists"],
        "transfer.replaceMessage": ["У этих аккаунтов уже есть запись, но в списке аккаунтов их нет — значит, прошлая попытка не завершилась. Заменить запись новым ключом?", "У цих акаунтів уже є запис, але в списку акаунтів їх немає — отже, минула спроба не завершилася. Замінити запис новим ключем?", "These accounts already have a record, but they are not in the account list — the previous attempt did not finish. Replace the record with the new key?"],
        "transfer.replaceAction": ["Заменить", "Замінити", "Replace"],
        "transfer.exportFooter": ["Несколько аккаунтов выгружаются одним архивом, один — парой файлов.", "Кілька акаунтів вивантажуються одним архівом, один — парою файлів.", "Several accounts are exported as one archive, a single one as a pair of files."],
        "transfer.importFolder": ["Добавить папку tdata", "Додати теку tdata", "Add a tdata folder"],
