        "loc.importFailed": ["Не удалось прочитать файл локализации", "Не вдалося прочитати файл локалізації", "Could not read the localization file"],
        "loc.activeFormat": ["Переведено %1 строк из %2", "Перекладено %1 рядків з %2", "%1 of %2 strings translated"],
        "loc.noneTitle": ["Перевод не подключён", "Переклад не підключено", "No translation applied"],
        "loc.noneSubtitle": ["Меню Whitegram на встроенном языке. Всего строк: %1", "Меню Whitegram вбудованою мовою. Усього рядків: %1", "The Whitegram menu uses a built-in language. Total strings: %1"],
        "loc.previewFormat": ["В файле %1 строк из %2", "У файлі %1 рядків з %2", "The file has %1 of %2 strings"],
        "loc.hint": ["Экспорт собирает все строки Whitegram в файл .wglocalizations. Переведите текст в кавычках и поделитесь файлом — другие подключат его импортом. Строки, которых нет в файле, останутся на встроенном языке.", "Експорт збирає всі рядки Whitegram у файл .wglocalizations. Перекладіть текст у лапках і поділіться файлом.", "Export collects every Whitegram string into a .wglocalizations file. Translate the text inside the quotes and share the file — others apply it with Import. Strings missing from the file keep the built-in language."],
        "msgStyle.color": ["Изменить цвет сообщения", "Змінити колір повідомлення", "Message color"],
        "msgStyle.colorTop": ["Цвет градиента сверху", "Колір градієнта згори", "Gradient color (top)"],
