        "msgStyle.glowColor": ["Изменить цвет свечения", "Змінити колір сяйва", "Glow color"],
        "msgStyle.typing": ["Добавить анимацию отправки", "Додати анімацію надсилання", "Typing animation"],
        "msgStyle.scope": ["Где применять", "Де застосовувати", "Where to apply"],
        "msgStyle.scope.thisChat": ["К этому чату", "До цього чату", "This chat"],
        "msgStyle.scope.allChats": ["Ко всем чатам", "До всіх чатів", "All chats"],
        "msgStyle.pickColor": ["Выберите цвет", "Оберіть колір", "Pick a color"],
        "msgStyle.preview.incoming": ["Обычное сообщение собеседника", "Звичайне повідомлення співрозмовника", "A regular incoming message"],
        "msgStyle.preview.outgoing": ["Так будет выглядеть ваше сообщение", "Так виглядатиме ваше повідомлення", "This is how your message will look"],
        "msgStyle.shape.none": ["Обычная", "Звичайна", "Default"],
        "msgStyle.shape.cloud": ["Облако", "Хмара", "Cloud"],
        "msgStyle.color.enabled": ["Свой цвет пузыря", "Власний колір бульбашки", "Custom bubble color"],
        "msgStyle.color.info": ["Верхний и нижний цвет градиента. Ваши сообщения увидят такими и другие пользователи Whitegram.", "Верхній і нижній колір градієнта. Ваші повідомлення такими побачать й інші користувачі Whitegram.", "Top and bottom gradient colors. Other Whitegram users see your messages this way too."],
        "msgStyle.shape.title": ["Форма пузыря", "Форма бульбашки", "Bubble shape"],
        "msgStyle.shape.info": ["Форма меняет контур пузыря. Рассчитана на широкое горизонтальное сообщение.", "Форма змінює контур бульбашки. Розрахована на широке горизонтальне повідомлення.", "The shape changes the bubble outline. It is designed for a wide horizontal message."],
        "msgStyle.glow.enabled": ["Свечение вокруг пузыря", "Сяйво навколо бульбашки", "Glow around the bubble"],
        "msgStyle.typing.enabled": ["Печатать текст по буквам", "Друкувати текст по літерах", "Type the text out letter by letter"],
        "msgStyle.typing.info": ["При появлении сообщения текст набирается посимвольно.", "Коли повідомлення з’являється, текст набирається посимвольно.", "When the message appears its text is typed out character by character."],
        "msgStyle.scope.info": ["Правила взаимоисключающие: оформление действует либо только в этом чате, либо во всех сразу.", "Правила взаємовиключні: оформлення діє або лише в цьому чаті, або в усіх одразу.", "The rules are mutually exclusive: the style applies either to this chat only or to every chat."],
        "msgStyle.reset": ["Сбросить оформление", "Скинути оформлення", "Reset appearance"],
        "msgStyle.syncFailed.title": ["Оформление не синхронизировано", "Оформлення не синхронізовано", "Appearance not synced"],
        "msgStyle.syncFailed.text": ["Не удалось отправить оформление на сервер Whitegram: пока оно применяется только у вас, собеседники видят обычные сообщения. Whitegram попробует отправить его снова автоматически.", "Не вдалося надіслати оформлення на сервер Whitegram: поки воно застосовується лише у вас. Whitegram спробує надіслати його знову автоматично.", "The appearance could not be uploaded to the Whitegram server: for now it applies only on your device, and other people see plain messages. Whitegram will retry automatically."],
        "s.bypassContentRestrictions": ["Открывать чаты, скрытые по правилам Telegram", "Відкривати чати, приховані за правилами Telegram", "Open chats hidden by Telegram rules"],
        "wh.bypassContentRestrictions": ["Каналы, группы и отдельные сообщения бывают помечены ограничением — по правилам Telegram, требованиям App Store или местных законов. Сам контент сервер при этом отдаёт полностью, прячет его именно приложение, поэтому пометку можно игнорировать и открывать такие чаты как обычные. Не действует на материалы о насилии над детьми и не помогает с каналами, которые Telegram удалил или заблокировал: там сервер просто не отдаёт данные, и обходить нечего.", "Канали, групи та окремі повідомлення бувають позначені обмеженням за правилами Telegram чи App Store. Контент сервер віддає повністю, ховає його саме застосунок, тому позначку можна ігнорувати.", "Channels, groups and individual messages can be flagged as restricted by Telegram's rules, App Store requirements or local law. The server still sends the content in full — it is the app that hides it, so the flag can be ignored. Does not apply to child abuse material, and does not help with channels Telegram has deleted or banned: there the server sends nothing at all."],
        "profileAbout.title": ["Описание Whitegram", "Опис Whitegram", "Whitegram bio"],
        "profileAbout.useWhitegram": ["Использовать функции\nWhitegram", "Використовувати функції\nWhitegram", "Use Whitegram\nfeatures"],
        "profileAbout.open": ["Редактировать описание", "Редагувати опис", "Edit bio"],
        "profileBadge.hintTap": ["Нажми!", "Натисни!", "Tap me!"],
        "profileAbout.replaceImage": ["Заменить картинку", "Замінити картинку", "Replace image"],
        "profileAbout.removeImage": ["Убрать картинку", "Прибрати картинку", "Remove image"],
        "profileAbout.hint": ["Описание Whitegram поддерживает форматирование, переносы строк, до 1200 символов и одну картинку. Его видят пользователи Whitegram; в обычном Telegram остаётся стандартное поле «о себе».", "Опис Whitegram підтримує форматування, переноси рядків, до 1200 символів і одну картинку.", "The Whitegram bio supports formatting, line breaks, up to 1200 characters and one image. Whitegram users see it; in regular Telegram the standard bio is shown."],
        "s.profileScene": ["Добавить спец. эффекты\nна задний фон профиля", "Додати спецефекти\nна тло профілю", "Add special effects\nto the profile background"],
        "wh.profileScene": ["Включает раздел спецэффектов для фона вашего профиля. Выбранный эффект уходит в Whitegram и виден всем пользователям Whitegram, которые к вам зайдут; в обычном Telegram профиль выглядит как всегда.", "Вмикає розділ спецефектів для тла вашого профілю. Обраний ефект бачать усі користувачі Whitegram.", "Enables special effects for your profile background. The chosen effect is shared through Whitegram and visible to every Whitegram user who opens your profile."],
        "s.profileSceneMode": ["Режим спец.эффектов", "Режим спецефектів", "Special effects mode"],
        "profileScene.none": ["Выключено", "Вимкнено", "Off"],
        "profileScene.snow": ["Снег", "Сніг", "Snow"],
        "profileScene.stars": ["Звёзды", "Зірки", "Stars"],
        "profileScene.clouds": ["Облака", "Хмари", "Clouds"],
        "profileScene.terminal": ["Терминал", "Термінал", "Terminal"],
        "profileScene.gradient": ["Градиент", "Градієнт", "Gradient"],
        "s.keepBannedChats": ["Оставаться в чате после бана", "Залишатися в чаті після бану", "Stay in chat after being banned"],
        "wh.keepBannedChats": ["После бана чат не закрывается и не превращается в заглушку: сохраняются название и аватарка, остаётся вся уже загруженная переписка, а плашка «вы больше не участник» не показывается. Новые сообщения при этом не приходят — после бана сервер Telegram историю не отдаёт, и обойти это на стороне приложения нельзя.", "Після бану чат не закривається: зберігаються назва й аватарка, залишається вся вже завантажена переписка. Нові повідомлення не надходять — після бану сервер історію не віддає.", "After a ban the chat is not closed and does not turn into a stub: the title and photo are kept, the already downloaded history stays readable, and the \"you are no longer a member\" bar is hidden. New messages will not arrive — after a ban Telegram's server stops serving that history, and no client can work around it."],
        "keychain.diagnostics": ["Диагностика Keychain", "Діагностика Keychain", "Keychain diagnostics"],
        "keychain.diagnostics.copy": ["Скопировать отчёт", "Скопіювати звіт", "Copy report"],
        "keychain.title": ["Резервные копии сессий", "Резервні копії сесій", "Session backups"],
        "keychain.intro": ["Копии сессий хранятся в Keychain и переживают удаление приложения: после переустановки аккаунты можно вернуть без входа по коду.\n\nКопии доступны, только если приложение подписано тем же сертификатом — при смене подписи iOS не даёт прочитать прежние записи.", "Копії сесій зберігаються в Keychain і переживають видалення застосунку: після перевстановлення акаунти можна повернути без входу за кодом.\n\nКопії доступні, лише якщо застосунок підписано тим самим сертифікатом.", "Session backups live in the Keychain and survive app deletion: after a reinstall you can restore accounts without an SMS login.\n\nThey stay readable only while the app is signed with the same certificate."],
        "keychain.sessionsHeader": ["Сохранённые аккаунты", "Збережені акаунти", "Saved accounts"],
        "keychain.empty": ["Копий пока нет. Нажмите «Сохранить активные аккаунты».", "Копій поки немає. Натисніть «Зберегти активні акаунти».", "No backups yet. Tap “Back up active accounts”."],
        "keychain.session.active": ["Уже добавлен", "Вже додано", "Already added"],
        "keychain.saveAll": ["Сохранить активные аккаунты", "Зберегти активні акаунти", "Back up active accounts"],
        "keychain.restoreAll": ["Восстановить все аккаунты", "Відновити всі акаунти", "Restore all accounts"],
        "keychain.restoreAlreadyActive": ["Эти аккаунты уже подключены — восстанавливать нечего.", "Ці акаунти вже підключено — відновлювати нічого.", "These accounts are already connected — nothing to restore."],
        "keychain.result.title": ["Восстановление сессий", "Відновлення сесій", "Session restore"],
        "keychain.result.created": ["Создали записи аккаунтов — сейчас проверим ключи:", "Створили записи акаунтів — зараз перевіримо ключі:", "Account records created — verifying the keys:"],
        "keychain.result.alreadyActive": ["Уже подключены, копия не нужна:", "Вже підключені, копія не потрібна:", "Already connected, no restore needed:"],
        "keychain.result.alreadyHasRecord": ["Запись аккаунта уже есть в приложении — не трогаем её, чтобы не потерять рабочий вход. Если аккаунт не работает, выйдите из него и восстановите заново:", "Запис акаунта вже є в застосунку — не чіпаємо його, щоб не втратити робочий вхід. Якщо акаунт не працює, вийдіть із нього й відновіть заново:", "This account already has a record in the app — left untouched so a working login is not lost. If it does not work, log out of it and restore again:"],
        "bot.title": ["Боты", "Боти", "Bots"],
        "bot.intro": ["Бот подключается обычным аккаунтом: вы читаете и отвечаете на его переписку прямо здесь. У ботовой сессии нет списка чатов на сервере — собеседники появляются по мере того, как пишут.", "Бот підключається звичайним акаунтом: ви читаєте та відповідаєте на його листування просто тут.", "A bot connects as a regular account: you read and answer its chats right here. A bot session has no server-side chat list — people show up as they write."],
        "bot.myBots.header": ["Ваши боты", "Ваші боти", "Your bots"],
        "bot.myBots.loading": ["Загружаем список…", "Завантажуємо список…", "Loading…"],
        "bot.myBots.empty": ["У этого аккаунта нет ботов. Заведите бота в @BotFather и войдите по токену.", "У цього акаунта немає ботів. Створіть бота в @BotFather і увійдіть за токеном.", "This account owns no bots. Create one in @BotFather and sign in with its token."],
        "bot.alreadyAdded": ["Уже добавлен", "Вже додано", "Already added"],
        "bot.loginWithToken": ["Войти по токену", "Увійти за токеном", "Sign in with a token"],
        "bot.actionsFooter": ["Токен нигде не сохраняется: он используется один раз, чтобы получить ключ сессии. Новые боты создаются только в @BotFather.", "Токен ніде не зберігається. Нові боти створюються лише в @BotFather.", "The token is never stored: it is used once to obtain a session key. New bots are created in @BotFather only."],
        "bot.token.title": ["Токен бота", "Токен бота", "Bot token"],
        "bot.token.subtitle": ["Строка вида 123456789:AA… из BotFather.", "Рядок виду 123456789:AA… з BotFather.", "The 123456789:AA… string from BotFather."],
        "bot.twoPartsError": ["Нужны две части, разделённые знаком «|».", "Потрібні дві частини, розділені «|».", "Two parts separated by “|” are required."],
        "bot.token.exportRefused": ["Telegram не отдал токен этого бота приложению. Откройте @BotFather → /mybots → бот → API Token и вставьте строку сюда.", "Telegram не віддав токен цього бота застосунку. Відкрийте @BotFather → /mybots → бот → API Token і вставте рядок сюди.", "Telegram refused to hand this bot's token to the app. Open @BotFather → /mybots → the bot → API Token and paste the string here."],
        "bot.current.header": ["Текущий аккаунт", "Поточний акаунт", "Current account"],
        "bot.current.info": ["Вы под ботом. Сторис, звонки, контакты и статус «в сети» у ботовой сессии отсутствуют — это ограничение Telegram, а не приложения.", "Ви під ботом. Сторіс, дзвінки та контакти ботовій сесії недоступні.", "You are signed in as a bot. Stories, calls, contacts and online status do not exist for a bot session — that is a Telegram limitation."],
        "bot.manage.header": ["Управление ботом", "Керування ботом", "Bot settings"],
        "bot.manage.name": ["Имя", "Ім'я", "Name"],
        "bot.manage.about": ["Коротко о боте", "Коротко про бота", "About"],
        "bot.manage.about.hint": ["Показывается в профиле бота под именем.", "Показується у профілі бота під ім'ям.", "Shown in the bot profile under its name."],
        "bot.manage.description": ["Описание", "Опис", "Description"],
        "bot.manage.description.hint": ["Показывается на пустом экране чата до первого запуска.", "Показується на порожньому екрані чату.", "Shown on the empty chat screen before the first start."],
        "bot.manage.commands": ["Команды", "Команди", "Commands"],
        "bot.manage.commands.empty": ["Не заданы", "Не задані", "None"],
        "bot.manage.commands.hint": ["По одной в строке: /start — описание", "По одній у рядку: /start — опис", "One per line: /start — description"],
        "bot.manage.menuButton": ["Кнопка меню", "Кнопка меню", "Menu button"],
        "bot.manage.menuButton.default": ["По умолчанию", "За замовчуванням", "Default"],
        "bot.manage.menuButton.commands": ["Список команд", "Список команд", "Commands list"],
        "bot.manage.menuButton.webApp": ["Веб-приложение", "Вебзастосунок", "Web app"],
        "bot.manage.menuButton.webApp.hint": ["Подпись и ссылка через вертикальную черту.", "Підпис і посилання через вертикальну риску.", "Label and URL separated by a vertical bar."],
        "bot.manage.stars": ["Звёзды", "Зірки", "Stars"],
        "bot.manage.stars.format": ["Доступно %@, всего заработано %@", "Доступно %@, усього зароблено %@", "Available %@, earned in total %@"],
        "bot.manage.stars.unknown": ["Нажмите, чтобы обновить", "Натисніть, щоб оновити", "Tap to refresh"],
        "bot.manage.stars.unavailable": ["Сервер не отдал статистику по звёздам этому боту.", "Сервер не віддав статистику зірок.", "The server did not return Stars stats for this bot."],
        "bot.manage.saved": ["Сохранено", "Збережено", "Saved"],
        "bot.manage.saveFailed": ["Сервер отклонил изменение", "Сервер відхилив зміну", "The server rejected the change"],
        "bot.probe.header": ["Возможности сессии", "Можливості сесії", "Session capabilities"],
        "bot.probe.run": ["Проверить, что доступно", "Перевірити, що доступно", "Check what is available"],
        "bot.probe.running": ["Проверяем…", "Перевіряємо…", "Checking…"],
        "bot.probe.footer": ["Ограничения ботов не описаны в схеме API: метод есть у всех, а ответит ли сервер — выясняется только запросом. Проверка ничего не меняет, только читает.", "Обмеження ботів не описані у схемі API — перевірка лише читає.", "Bot restrictions are not encoded in the API schema: a method exists for everyone, but whether the server answers is only found out by asking. The check only reads."],
        "bot.probe.notForBots": ["Метод только для обычных аккаунтов — боту не положен. Это норма, а не ошибка.", "Метод лише для звичайних акаунтів — боту він не належить. Це норма, а не помилка.", "A user-only method — bots do not get it. This is normal, not an error."],
        "bot.badge": ["БОТ", "БОТ", "BOT"],
        "bot.login.progress.title": ["Входим ботом", "Входимо ботом", "Signing in as a bot"],
        "bot.login.progress.text": ["Меняем токен на ключ сессии. Номер телефона не нужен — это займёт пару секунд.", "Змінюємо токен на ключ сесії. Номер телефону не потрібен — це займе кілька секунд.", "Exchanging the token for a session key. No phone number needed — this takes a couple of seconds."],
        "bot.chatList.empty.title": ["Пока никто не написал", "Поки ніхто не написав", "Nobody has written yet"],
        "bot.chatList.empty.text": ["У ботовой сессии нет списка чатов на сервере — Telegram его боту не отдаёт. Собеседники появятся здесь сами, как только напишут боту.", "У ботової сесії немає списку чатів на сервері — Telegram його боту не віддає. Співрозмовники з'являться тут самі, щойно напишуть боту.", "A bot session has no server-side chat list — Telegram does not hand one to bots. People will appear here on their own as soon as they write to the bot."],
        "bot.logout.title": ["Выйти из бота?", "Вийти з бота?", "Log out of the bot?"],
        "bot.logout.text": ["Аккаунт будет убран только из Whitegram. Сам бот и его токен в BotFather останутся как есть — его можно добавить снова.", "Акаунт буде прибрано лише з Whitegram. Сам бот і його токен залишаться.", "The account will be removed from Whitegram only. The bot itself and its BotFather token stay as they are — you can add it again."],
        "bot.logout.action": ["Выйти", "Вийти", "Log Out"],
        "bot.error.title": ["Не удалось войти", "Не вдалося увійти", "Could not sign in"],
        "bot.error.alreadyAdded": ["Этот бот уже добавлен в приложение.", "Цього бота вже додано.", "This bot is already added."],
        "bot.error.invalidToken": ["Токен недействителен. Проверьте его в BotFather.", "Токен недійсний.", "The token is invalid. Check it in BotFather."],
        "bot.error.floodWait": ["Слишком много попыток. Повторите через %d с.", "Забагато спроб. Повторіть через %d с.", "Too many attempts. Try again in %d s."],
        "bot.error.apiId": ["Сервер отклонил api_id этой сборки.", "Сервер відхилив api_id.", "The server rejected this build's api_id."],
        "bot.error.notABot": ["Похоже, это не токен бота.", "Схоже, це не токен бота.", "That does not look like a bot token."],
        "bot.error.network": ["Нет связи с сервером.", "Немає зв'язку із сервером.", "No connection to the server."],
        "bot.error.notOwner": ["Этим ботом владеет другой аккаунт.", "Цим ботом володіє інший акаунт.", "This bot belongs to another account."],
        "bot.error.notFound": ["Бот не найден.", "Бота не знайдено.", "Bot not found."],
        "bot.error.rpc": ["Сервер ответил ошибкой: %@", "Сервер відповів помилкою: %@", "The server returned an error: %@"],
        "keychain.restoreRejected.title": ["Сервер отклонил ключ", "Сервер відхилив ключ", "The server rejected the key"],
        "keychain.restoreRejected.text": ["Записи созданы, но эти аккаунты не поднялись: Telegram отклонил сохранённый ключ. Так бывает, если сессию завершили с другого устройства или менялся облачный пароль. Для них нужен обычный вход по коду.", "Записи створено, але ці акаунти не піднялися: Telegram відхилив збережений ключ. Для них потрібен звичайний вхід за кодом.", "The records were created, but these accounts did not come up: Telegram rejected the stored key. This happens when the session was terminated elsewhere or the cloud password changed. They need a normal login."],
        "keychain.restore": ["Восстановить", "Відновити", "Restore"],
        "keychain.deleteOne": ["Удалить копию", "Видалити копію", "Delete backup"],
        "keychain.deleteAll": ["Удалить все копии", "Видалити всі копії", "Delete all backups"],
        "keychain.deleteAllConfirm": ["Все резервные копии сессий будут удалены из Keychain. Отменить нельзя.", "Усі резервні копії сесій буде видалено з Keychain. Скасувати неможливо.", "All session backups will be removed from the Keychain. This cannot be undone."],
        "keychain.actionsFooter": ["Нажмите на аккаунт, чтобы восстановить его отдельно или убрать копию.", "Натисніть на акаунт, щоб відновити його окремо або прибрати копію.", "Tap an account to restore it individually or remove its backup."],
        "profile.registrationDate.add": ["Указать", "Вказати", "Add"],
        "profile.registrationDate.year": ["Год, например 2019", "Рік, наприклад 2019", "Year, e.g. 2019"],
        "profile.registrationDate.month": ["Месяц (1–12), можно оставить пустым", "Місяць (1–12), можна лишити порожнім", "Month (1–12), optional"],
        "profile.registrationDate.day": ["День (1–31), можно оставить пустым", "День (1–31), можна лишити порожнім", "Day (1–31), optional"],
        "profile.registrationDate.editorHint": ["Укажите, когда был зарегистрирован аккаунт. Достаточно одного года — месяц и день можно не заполнять. Эта дата будет видна в вашем профиле другим пользователям Whitegram и поможет точнее показывать примерные даты регистрации у остальных.", "Вкажіть, коли було зареєстровано акаунт. Досить одного року — місяць і день можна не заповнювати.", "Tell us when this account was registered. The year alone is enough — month and day are optional. The date is shown in your profile to other Whitegram users and helps estimate registration dates for everyone else more precisely."],
        "profile.scammerWarningLabel": ["ВНИМАНИЕ", "УВАГА", "WARNING"],
        "profile.scammerWarningText": ["Этот аккаунт внесён в нашу базу данных мошенников. Этот человек может вас обмануть, украсть ваш аккаунт или NFT подарки. Будьте крайне осторожны!", "Цей акаунт внесено до нашої бази шахраїв. Ця людина може вас обманути, вкрасти ваш акаунт або NFT-подарунки. Будьте дуже обережні!", "This account is listed in our scammer database. This person may deceive you or steal your account or NFT gifts. Be extremely careful!"],
        "wall.blockConfirm.msg": ["Этот пользователь больше не сможет видеть вашу стену и писать на ней.", "Цей користувач більше не зможе бачити вашу стіну та писати на ній.", "This user will no longer be able to see your wall or post on it."],
        "wall.blockConfirm.titleFormat": ["Заблокировать %@?", "Заблокувати %@?", "Block %@?"],
        "wall.blockError.msg": ["Не удалось заблокировать пользователя. Проверьте соединение с Whitegram API.", "Не вдалося заблокувати користувача. Перевірте з'єднання з Whitegram API.", "Failed to block user. Check your Whitegram API connection."],
        "wall.blockUser": ["Заблокировать пользователя", "Заблокувати користувача", "Block User"],
